def wrap(text, width):
    lines = []
    paragraphs = text.split('\n')

    for paragraph in paragraphs:
        words = []
        for word in paragraph.split():
            if len(word) <= width:
                words.append(word)
            else:
                for i in range(0, len(word), width):
                    words.append(word[i:i+width])

        if not words:
            lines.append('')
        else:
            current_line = []
            current_length = 0

            for word in words:
                word_len = len(word)
                if current_line:
                    needed = current_length + 1 + word_len
                else:
                    needed = word_len

                if needed <= width:
                    current_line.append(word)
                    current_length = needed
                else:
                    if current_line:
                        lines.append(' '.join(current_line))
                    current_line = [word]
                    current_length = word_len

            if current_line:
                lines.append(' '.join(current_line))

    return lines

